[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "packing-list-london",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "packing-list-london",
      "components": [
        {
          "id": "root",
          "component": "Column",
          "properties": {
            "children": [
              {
                "id": "header_card",
                "component": "Card",
                "properties": {
                  "children": [
                    {
                      "id": "header_column",
                      "component": "Column",
                      "properties": {
                        "children": [
                          {
                            "id": "title_text",
                            "component": "Text",
                            "properties": {
                              "text": "Packing List: Business Trip to London",
                              "style": "title"
                            }
                          },
                          {
                            "id": "dates_text",
                            "component": "Text",
                            "properties": {
                              "text": "Dates: 2024-10-15 to 2024-10-17",
                              "style": "body"
                            }
                          },
                          {
                            "id": "forecast_text",
                            "component": "Text",
                            "properties": {
                              "text": "Forecast: 10-14°C, cool, wet, and windy with heavy rain.",
                              "style": "body"
                            }
                          }
                        ]
                      }
                    }
                  ]
                }
              },
              {
                "id": "assumptions_text",
                "component": "Text",
                "properties": {
                  "text": "Assumptions: This packing list assumes a business casual to business formal dress code, optimized for a carry-on. The focus is on layering to adapt to variable weather.",
                  "style": "caption"
                }
              },
              {
                "id": "packing_tabs",
                "component": "Tabs",
                "properties": {
                  "tabs": [
                    {
                      "label": "Outerwear",
                      "icon": "/trench-coat",
                      "contentComponentId": "outerwear_content"
                    },
                    {
                      "label": "Footwear",
                      "icon": "/boots",
                      "contentComponentId": "footwear_content"
                    },
                    {
                      "label": "Business Attire",
                      "icon": "/briefcase",
                      "contentComponentId": "attire_content"
                    },
                    {
                      "label": "Casual",
                      "contentComponentId": "casual_content"
                    },
                    {
                      "label": "Essentials",
                      "icon": "/passport",
                      "contentComponentId": "essentials_content"
                    },
                    {
                      "label": "Toiletries",
                      "icon": "/toothbrush",
                      "contentComponentId": "toiletries_content"
                    }
                  ]
                }
              },
              {
                "id": "packing_tip_card",
                "component": "Card",
                "properties": {
                  "children": [
                    {
                      "id": "packing_tip_column",
                      "component": "Column",
                      "properties": {
                        "children": [
                          {
                            "id": "packing_tip_title",
                            "component": "Text",
                            "properties": {
                              "text": "Packing Tip",
                              "style": "headline"
                            }
                          },
                          {
                            "id": "packing_tip_text",
                            "component": "Text",
                            "properties": {
                              "text": "Lay out all your items before packing to ensure they coordinate. Roll clothing items to save space and prevent wrinkles. Keep your umbrella and rain jacket easily accessible for your arrival.",
                              "style": "body"
                            }
                          }
                        ]
                      }
                    }
                  ]
                }
              },
              {
                "id": "images_row",
                "component": "Row",
                "properties": {
                  "spacing": 8,
                  "children": [
                    {
                      "id": "image_card_1",
                      "component": "Card",
                      "properties": {
                        "children": [
                          {
                            "id": "image_col_1",
                            "component": "Column",
                            "properties": {
                              "children": [
                                {
                                  "id": "image_1",
                                  "component": "Image",
                                  "properties": {
                                    "source": "/london-trench-coat",
                                    "aspectRatio": "1:1"
                                  }
                                },
                                {
                                  "id": "image_text_1",
                                  "component": "Text",
                                  "properties": {
                                    "text": "Key Outerwear: A classic waterproof trench coat.",
                                    "style": "caption"
                                  }
                                }
                              ]
                            }
                          }
                        ]
                      }
                    },
                    {
                      "id": "image_card_2",
                      "component": "Card",
                      "properties": {
                        "children": [
                          {
                            "id": "image_col_2",
                            "component": "Column",
                            "properties": {
                              "children": [
                                {
                                  "id": "image_2",
                                  "component": "Image",
                                  "properties": {
                                    "source": "/chelsea-boots",
                                    "aspectRatio": "1:1"
                                  }
                                },
                                {
                                  "id": "image_text_2",
                                  "component": "Text",
                                  "properties": {
                                    "text": "Appropriate Footwear: Waterproof leather Chelsea boots.",
                                    "style": "caption"
                                  }
                                }
                              ]
                            }
                          }
                        ]
                      }
                    },
                    {
                      "id": "image_card_3",
                      "component": "Card",
                      "properties": {
                        "children": [
                          {
                            "id": "image_col_3",
                            "component": "Column",
                            "properties": {
                              "children": [
                                {
                                  "id": "image_3",
                                  "component": "Image",
                                  "properties": {
                                    "source": "/uk-adapter",
                                    "aspectRatio": "1:1"
                                  }
                                },
                                {
                                  "id": "image_text_3",
                                  "component": "Text",
                                  "properties": {
                                    "text": "Essential Tech: A UK Type G power adapter.",
                                    "style": "caption"
                                  }
                                }
                              ]
                            }
                          }
                        ]
                      }
                    }
                  ]
                }
              },
              {
                "id": "actions_row",
                "component": "Row",
                "properties": {
                  "spacing": 8,
                  "children": [
                    {
                      "id": "action_button_1",
                      "component": "Button",
                      "properties": {
                        "label": "Shop UK Adapters",
                        "action": {
                          "functionCall": {
                            "call": "openUrl",
                            "args": {
                              "url": "https://www.example.com/electronics/travel-adapters"
                            }
                          }
                        }
                      }
                    },
                    {
                      "id": "action_button_2",
                      "component": "Button",
                      "properties": {
                        "label": "View Waterproof Shoes",
                        "action": {
                          "functionCall": {
                            "call": "openUrl",
                            "args": {
                              "url": "https://www.example.com/mens-womens-footwear/waterproof"
                            }
                          }
                        }
                      }
                    },
                    {
                      "id": "action_button_3",
                      "component": "Button",
                      "properties": {
                        "label": "Check Tube Status",
                        "action": {
                          "functionCall": {
                            "call": "openUrl",
                            "args": {
                              "url": "https://www.example.com/london-transport-live-status"
                            }
                          }
                        }
                      }
                    }
                  ]
                }
              }
            ]
          }
        },
        {
          "id": "outerwear_content",
          "component": "Column",
          "properties": {
            "children": [
              {
                "id": "outerwear_desc",
                "component": "Text",
                "properties": {
                  "text": "A versatile, weather-resistant outer layer is critical for this trip.",
                  "style": "body"
                }
              },
              {
                "id": "outerwear_list",
                "component": "List",
                "properties": {
                  "children": [
                    {
                      "id": "item_trench",
                      "component": "ListItem",
                      "properties": {
                        "leadingComponentId": "check_trench",
                        "primaryText": "Waterproof Trench Coat or Smart Rain Jacket (x1)",
                        "supportingText": "Choose a neutral color like black, navy, or beige."
                      }
                    },
                    {
                      "id": "item_umbrella",
                      "component": "ListItem",
                      "properties": {
                        "leadingComponentId": "check_umbrella",
                        "primaryText": "Compact Travel Umbrella (x1)",
                        "supportingText": "Essential for the heavy rain forecasted."
                      }
                    },
                    {
                      "id": "item_scarf",
                      "component": "ListItem",
                      "properties": {
                        "leadingComponentId": "check_scarf",
                        "primaryText": "Wool Scarf (x1)",
                        "supportingText": "Provides warmth against the wind and adds a professional touch."
                      }
                    }
                  ]
                }
              }
            ]
          }
        },
        {
          "id": "footwear_content",
          "component": "Column",
          "properties": {
            "children": [
              {
                "id": "footwear_desc",
                "component": "Text",
                "properties": {
                  "text": "Comfort and water resistance are key. You will likely be walking between transport and meetings.",
                  "style": "body"
                }
              },
              {
                "id": "footwear_list",
                "component": "List",
                "properties": {
                  "children": [
                    {
                      "id": "item_boots",
                      "component": "ListItem",
                      "properties": {
                        "leadingComponentId": "check_boots",
                        "primaryText": "Waterproof Leather Shoes or Boots (x1 pair)",
                        "supportingText": "e.g., Chelsea boots, brogues, or loafers. Avoid suede."
                      }
                    },
                    {
                      "id": "item_dress_shoes",
                      "component": "ListItem",
                      "properties": {
                        "leadingComponentId": "check_dress_shoes",
                        "primaryText": "Smart Dress Shoes (x1 pair)",
                        "supportingText": "A second, comfortable pair for indoor meetings or dinners."
                      }
                    }
                  ]
                }
              }
            ]
          }
        },
        {
          "id": "attire_content",
          "component": "Column",
          "properties": {
            "children": [
              {
                "id": "attire_desc",
                "component": "Text",
                "properties": {
                  "text": "Focus on layering and fabrics like merino wool, cashmere, and cotton blends that provide warmth without bulk.",
                  "style": "body"
                }
              },
              {
                "id": "attire_list",
                "component": "List",
                "properties": {
                  "children": [
                    {
                      "id": "item_suit",
                      "component": "ListItem",
                      "properties": {
                        "leadingComponentId": "check_suit",
                        "primaryText": "Suit or Blazer/Trousers/Skirt Combo (x2)",
                        "supportingText": "Choose versatile pieces in navy, grey, or black."
                      }
                    },
                    {
                      "id": "item_shirts",
                      "component": "ListItem",
                      "properties": {
                        "leadingComponentId": "check_shirts",
                        "primaryText": "Dress Shirts or Blouses (x3)"
                      }
                    },
                    {
                      "id": "item_sweater",
                      "component": "ListItem",
                      "properties": {
                        "leadingComponentId": "check_sweater",
                        "primaryText": "Fine-Knit Sweater or Cardigan (x2)",
                        "supportingText": "For layering under a blazer on colder days."
                      }
                    },
                    {
                      "id": "item_trousers",
                      "component": "ListItem",
                      "properties": {
                        "leadingComponentId": "check_trousers",
                        "primaryText": "Business-appropriate Trousers or Skirt (x1, extra)"
                      }
                    },
                    {
                      "id": "item_belt",
                      "component": "ListItem",
                      "properties": {
                        "leadingComponentId": "check_belt",
                        "primaryText": "Belt (x1)"
                      }
                    }
                  ]
                }
              }
            ]
          }
        },
        {
          "id": "casual_content",
          "component": "Column",
          "properties": {
            "children": [
              {
                "id": "casual_desc",
                "component": "Text",
                "properties": {
                  "text": "For travel, evenings, or any downtime.",
                  "style": "body"
                }
              },
              {
                "id": "casual_list",
                "component": "List",
                "properties": {
                  "children": [
                    {
                      "id": "item_jeans",
                      "component": "ListItem",
                      "properties": {
                        "leadingComponentId": "check_jeans",
                        "primaryText": "Dark Jeans or Chinos (x1 pair)"
                      }
                    },
                    {
                      "id": "item_casual_shirt",
                      "component": "ListItem",
                      "properties": {
                        "leadingComponentId": "check_casual_shirt",
                        "primaryText": "Casual Shirt or Sweater (x1)"
                      }
                    },
                    {
                      "id": "item_underwear",
                      "component": "ListItem",
                      "properties": {
                        "leadingComponentId": "check_underwear",
                        "primaryText": "Underwear & Socks (x3 pairs)",
                        "supportingText": "Consider one pair of wool socks for the coldest day."
                      }
                    },
                    {
                      "id": "item_sleepwear",
                      "component": "ListItem",
                      "properties": {
                        "leadingComponentId": "check_sleepwear",
                        "primaryText": "Sleepwear (x1 set)"
                      }
                    }
                  ]
                }
              }
            ]
          }
        },
        {
          "id": "essentials_content",
          "component": "List",
          "properties": {
            "children": [
              {
                "id": "item_passport",
                "component": "ListItem",
                "properties": {
                  "leadingComponentId": "check_passport",
                  "primaryText": "Passport & Travel Documents"
                }
              },
              {
                "id": "item_wallet",
                "component": "ListItem",
                "properties": {
                  "leadingComponentId": "check_wallet",
                  "primaryText": "Wallet (with GBP/contactless cards)"
                }
              },
              {
                "id": "item_phone",
                "component": "ListItem",
                "properties": {
                  "leadingComponentId": "check_phone",
                  "primaryText": "Phone & Charger"
                }
              },
              {
                "id": "item_laptop",
                "component": "ListItem",
                "properties": {
                  "leadingComponentId": "check_laptop",
                  "primaryText": "Laptop/Tablet & Charger"
                }
              },
              {
                "id": "item_adapter",
                "component": "ListItem",
                "properties": {
                  "leadingComponentId": "check_adapter",
                  "primaryText": "UK Power Adapter (Type G)"
                }
              },
              {
                "id": "item_powerbank",
                "component": "ListItem",
                "properties": {
                  "leadingComponentId": "check_powerbank",
                  "primaryText": "Portable Power Bank"
                }
              },
              {
                "id": "item_cards",
                "component": "ListItem",
                "properties": {
                  "leadingComponentId": "check_cards",
                  "primaryText": "Business Cards"
                }
              },
              {
                "id": "item_notebook",
                "component": "ListItem",
                "properties": {
                  "leadingComponentId": "check_notebook",
                  "primaryText": "Notebook & Pen"
                }
              }
            ]
          }
        },
        {
          "id": "toiletries_content",
          "component": "List",
          "properties": {
            "children": [
              {
                "id": "item_bag",
                "component": "ListItem",
                "properties": {
                  "leadingComponentId": "check_bag",
                  "primaryText": "Toiletry Bag with travel-sized essentials",
                  "supportingText": "Toothbrush, toothpaste, deodorant, etc."
                }
              },
              {
                "id": "item_skincare",
                "component": "ListItem",
                "properties": {
                  "leadingComponentId": "check_skincare",
                  "primaryText": "Skincare/Moisturizer",
                  "supportingText": "Wind can be drying."
                }
              },
              {
                "id": "item_meds",
                "component": "ListItem",
                "properties": {
                  "leadingComponentId": "check_meds",
                  "primaryText": "Any personal medications"
                }
              }
            ]
          }
        },
        {
          "id": "check_trench",
          "component": "Checkbox"
        },
        {
          "id": "check_umbrella",
          "component": "Checkbox"
        },
        {
